class Solution:
    def minWaitingTime(self, period, lights, arrivalTime):
        L = max(lights)
        rs = {t % period for t in arrivalTime}
        def can(P):
            return all(r < L or period - r <= P for r in rs)
        lo, hi = 0, period - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid): hi = mid
            else: lo = mid + 1
        return lo

