class Solution {
public:
    int minWaitingTime(int period, vector<int>& lights, vector<int>& arrivalTime) {
        int L = *max_element(lights.begin(), lights.end());
        unordered_set<int> rs;
        for (int t : arrivalTime) rs.insert(t % period);
        auto can = [&](long long P) {
            for (int r : rs)
                if (r >= L && period - r > P) return false;
            return true;
        };
        long long lo = 0, hi = period - 1;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (can(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};

