class Solution {
    public int minWaitingTime(int period, int[] lights, int[] arrivalTime) {
        int L = 0;
        for (int x : lights) L = Math.max(L, x);
        java.util.Set<Integer> rs = new java.util.HashSet<>();
        for (int t : arrivalTime) rs.add(t % period);
        long lo = 0, hi = period - 1;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            boolean ok = true;
            for (int r : rs)
                if (r >= L && period - r > mid) { ok = false; break; }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
}

