    const rs = new Set(arrivalTime.map(t => t % period));
    const can = P => [...rs].every(r => r < L || period - r <= P);
    let lo = 0, hi = period - 1;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (can(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};

